            '        int[] a = {0, 1, 0, 3, 12};',
            '        int w = 0;',
            '        for (int r = 0; r < a.length; r++) {',
            '            if (a[r] != 0) a[w++] = a[r];',
            '        }',
            '        for (int i = w; i < a.length; i++) a[i] = 0;',
            '        System.out.println(Arrays.toString(a));',
            '    }',
