            '  for (var i = w; i < a.length; i++) a[i] = 0;',
            '  print(a);',
            '}',
            '---',
            '##1## Dart entry point. [main]({dart:main})',
            '##2## List with zeros. [List]({dart:List})',
            '##3## Write pointer at 0. [var]({dart:var})',
            '##4## Read pointer scans all indices. [for]({dart:for})',
            '##5## Copy non-zeros forward. [if]({dart:if})',
            '##7## Fill remaining with zeros. [for]({dart:for})',
            '##8## Print the result. [print]({dart:print})',
            '~~~',
            '',
            '~~~io',
            'input: a = [0, 1, 0, 3, 12]',
            'output:',
            '1 3 12 0 0',
