            '~~~problem',
            'title: Contains Duplicate',
            'difficulty: easy',
            'source: LeetCode 217 · Amazon, Apple',
            'tags: array, hashset',
            'statement: Return true if any value appears at least twice.',
            'approach: Insert into a set as you scan; if insertion fails, a duplicate exists. Or sort and check neighbors.',
            'time: O(n) (hash) / O(n log n) (sort)',
            'space: O(n) / O(1)',
            'solution: containsduplicate',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: containsduplicate',
            '#include <stdio.h>',
            '#include <stdbool.h>',
            'bool containsDuplicate(int* nums, int n) {',
            '    for (int i = 0; i < n; i++) {',
            '        for (int j = i + 1; j < n; j++) {',
            '            if (nums[i] == nums[j]) return true;',
            '        }',
            '    }',
            '    return false;',
            '}',
            'int main() {',
            '    int nums[] = {1, 2, 3, 1};',
            '    int n = 4;',
            '    printf("%s\\n", containsDuplicate(nums, n) ? "true" : "false");',
            '    return 0;',
            '}',
            '---',
            '##1## Standard I/O header. [stdio]({c:stdio})',
            '##2## Boolean type for the return value. [stdbool](https://en.cppreference.com/w/c/header/stdbool)',
            '##3## Function checks for duplicates. [Functions](https://www.learn-c.org/en/Functions)',
            '##4## Outer loop picks the first element. [For loops]({c:for})',
            '##5## Inner loop checks all later elements. [For loops]({c:for})',
            '##6## Found a duplicate. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##8## No duplicates found. [return]({c:return})',
            '##9## Entry point. [main]({c:main})',
            '##10## Sample array with a duplicate. [Arrays]({c:array})',
            '##12## Print result as true/false. [printf]({c:printf})',
            '##13## Exit successfully. [return]({c:return})',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: containsduplicate',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'bool containsDuplicate(vector<int>& nums) {',
            '    unordered_set<int> seen;',
            '    for (int x : nums) {',
            '        if (!seen.insert(x).second) return true;',
            '    }',
            '    return false;',
            '}',
            'int main() {',
            '    vector<int> nums = {1, 2, 3, 1};',
            '    cout << (containsDuplicate(nums) ? "true" : "false") << "\\n";',
            '    return 0;',
            '}',
            '---',
            '##1## Whole standard library. [bits/stdc++.h](https://www.geeksforgeeks.org/bitsstdc-h-c/)',
            '##2## Avoids `std::` prefix. [namespace]({cpp:namespace})',
            '##3## Function takes a vector reference. [vector]({cpp:vector})',
            '##4## Hash set to track seen values. [unordered_set](https://en.cppreference.com/w/cpp/container/unordered_set)',
            '##5## Iterate over elements. [for](https://en.cppreference.com/w/cpp/language/range-for)',
            '##6## Insert returns false if already present. [insert](https://en.cppreference.com/w/cpp/container/unordered_set/insert)',
            '##8## No duplicates. [return](https://en.cppreference.com/w/cpp/language/return)',
            '##9## Entry point. [main]({cpp:main})',
            '##10## Sample data. [vector]({cpp:vector})',
            '##11## Print result. [cout]({cpp:cout})',
            '##12## Success exit. [return](https://en.cppreference.com/w/cpp/language/return)',
            '~~~',
            '',
            '~~~explain',
            'lang: java',
            'group: containsduplicate',
            'import java.util.*;',
            'public class Main {',
            '    static boolean containsDuplicate(int[] nums) {',
            '        Set<Integer> seen = new HashSet<>();',
            '        for (int x : nums) {',
            '            if (!seen.add(x)) return true;',
            '        }',
            '        return false;',
            '    }',
            '    public static void main(String[] args) {',
            '        int[] nums = {1, 2, 3, 1};',
            '        System.out.println(containsDuplicate(nums));',
            '    }',
            '}',
            '---',
            '##1## Imports utility classes. [import]({java:import})',
            '##2## All methods live in a class. [class]({java:class})',
            '##3## Static method checks for duplicates. [static](https://docs.oracle.com/javase/tutorial/java/javaOO/classvariables.html)',
            '##4## Hash set for seen values. [HashSet](https://docs.oracle.com/javase/8/docs/api/java/util/HashSet.html)',
            '##5## Iterate over the array. [for]({java:for})',
            '##6## `add` returns false if already present. [Set.add](https://docs.oracle.com/javase/8/docs/api/java/util/Set.html#add-E-)',
            '##8## No duplicates. [return]({java:return})',
            '##9## Entry point. [main]({java:main})',
            '##10## Sample data. [Arrays](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/arrays.html)',
            '##11## Print the result. [println]({java:println})',
            '~~~',
            '',
            '~~~explain',
            'lang: python',
            'group: containsduplicate',
            'def main():',
            '    nums = [1, 2, 3, 1]',
            '    seen = set()',
            '    for x in nums:',
            '        if x in seen:',
            '            print("true")',
            '            return',
            '        seen.add(x)',
            '    print("false")',
            '',
            'main()',
            '---',
            '##1## Function definition. [def]({python:def})',
            '##2## Input list. [list]({python:list})',
            '##3## Set to track seen values. [set]({python:set})',
            '##4## Iterate over elements. [for]({python:for})',
            '##5## Check if already seen. [if]({python:if})',
            '##6## Duplicate found. [print]({python:print})',
            '##7## Exit early. [return](https://docs.python.org/3/reference/simple_stmts.html#return)',
            '##8## Add to seen set. [set]({python:set})',
            '##9## No duplicates. [print]({python:print})',
            '##11## Run the function. [main]({python:main})',
            '~~~',
            '',
            '~~~explain',
            'lang: dart',
            'group: containsduplicate',
            'void main() {',
            '  var nums = [1, 2, 3, 1];',
            '  var seen = <int>{};',
            '  for (var x in nums) {',
            '    if (!seen.add(x)) {',
            '      print("true");',
