            '~~~problem',
            'title: Remove Duplicates from Sorted Array',
            'difficulty: easy',
            'source: LeetCode 26 · Meta, Bloomberg',
            'tags: array, two-pointers, in-place',
            'statement: Remove duplicates in-place from a sorted array and return the new length.',
            'approach: Write pointer `w`. For each `r`, if `arr[r] != arr[w-1]`, copy `arr[r]` to `arr[w++]`. The relative order stays sorted.',
            'time: O(n)',
            'space: O(1)',
            'solution: removeduplicates',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: removeduplicates',
            '#include <stdio.h>',
            'int removeDuplicates(int* nums, int n) {',
            '    if (n == 0) return 0;',
            '    int w = 1;',
            '    for (int r = 1; r < n; r++) {',
            '        if (nums[r] != nums[w - 1]) {',
            '            nums[w] = nums[r];',
            '            w++;',
            '        }',
            '    }',
            '    return w;',
            '}',
            'int main() {',
            '    int nums[] = {0, 0, 1, 1, 1, 2};',
            '    int n = 6;',
            '    int k = removeDuplicates(nums, n);',
            '    for (int i = 0; i < k; i++) printf("%d ", nums[i]);',
            '    printf("\\n");',
            '    return 0;',
            '}',
            '---',
            '##1## Standard I/O header. [stdio]({c:stdio})',
            '##2## Function removes duplicates in-place. [Functions](https://www.learn-c.org/en/Functions)',
            '##3## Empty array edge case. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##4## Write pointer starts at index 1. [Variables](https://www.learn-c.org/en/Variables)',
            '##5## Read pointer scans from index 1. [For loops]({c:for})',
            '##6## Compare with the last unique element. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##7## Copy unique element forward. [Arrays]({c:array})',
            '##8## Advance write pointer. [Variables](https://www.learn-c.org/en/Variables)',
            '##10## Return new length. [return]({c:return})',
            '##11## Entry point. [main]({c:main})',
            '##12## Sorted array with duplicates. [Arrays]({c:array})',
            '##14## Get the new length. [Functions](https://www.learn-c.org/en/Functions)',
            '##15## Print unique elements. [For loops]({c:for})',
            '##17## Exit successfully. [return]({c:return})',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: removeduplicates',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int removeDuplicates(vector<int>& nums) {',
            '    if (nums.empty()) return 0;',
            '    int w = 1;',
            '    for (int r = 1; r < nums.size(); r++) {',
            '        if (nums[r] != nums[w - 1]) nums[w++] = nums[r];',
            '    }',
            '    return w;',
            '}',
            'int main() {',
            '    vector<int> nums = {0, 0, 1, 1, 1, 2};',
            '    int k = removeDuplicates(nums);',
            '    for (int i = 0; i < k; i++) cout << nums[i] << " ";',
            '    cout << "\\n";',
            '    return 0;',
            '}',
            '---',
            '##1## Whole standard library. [bits/stdc++.h](https://www.geeksforgeeks.org/bitsstdc-h-c/)',
            '##2## Avoids `std::` prefix. [namespace]({cpp:namespace})',
            '##3## Function takes vector by reference. [vector]({cpp:vector})',
            '##4## Empty check. [empty](https://en.cppreference.com/w/cpp/container/vector/empty)',
            '##5## Write pointer at 1. [Variables](https://www.learn-c.org/en/Variables)',
            '##6## Read pointer scans remaining. [For loops](https://en.cppreference.com/w/cpp/language/for)',
            '##7## Copy unique element. [If statements](https://en.cppreference.com/w/cpp/language/if)',
            '##9## Return new size. [return](https://en.cppreference.com/w/cpp/language/return)',
            '##10## Entry point. [main]({cpp:main})',
            '##11## Sorted input. [vector]({cpp:vector})',
            '##12## Get new length. [Functions](https://www.learn-c.org/en/Functions)',
            '##13## Print unique elements. [For loops](https://en.cppreference.com/w/cpp/language/for)',
            '##15## Success exit. [return](https://en.cppreference.com/w/cpp/language/return)',
            '~~~',
            '',
            '~~~explain',
            'lang: java',
            'group: removeduplicates',
            'import java.util.*;',
            'public class Main {',
            '    static int removeDuplicates(int[] nums) {',
            '        if (nums.length == 0) return 0;',
            '        int w = 1;',
            '        for (int r = 1; r < nums.length; r++) {',
            '            if (nums[r] != nums[w - 1]) nums[w++] = nums[r];',
            '        }',
            '        return w;',
            '    }',
            '    public static void main(String[] args) {',
            '        int[] nums = {0, 0, 1, 1, 1, 2};',
            '        int k = removeDuplicates(nums);',
            '        for (int i = 0; i < k; i++) System.out.print(nums[i] + " ");',
            '        System.out.println();',
            '    }',
            '}',
