            'int maxArea(vector<int>& h) {',
            '    int l = 0, r = h.size() - 1, best = 0;',
            '    while (l < r) {',
            '        best = max(best, min(h[l], h[r]) * (r - l));',
            '        if (h[l] < h[r]) l++;',
            '        else r--;',
            '    }',
            '    return best;',
            '}',
