            '~~~explain',
            'lang: java',
            'group: containerwater',
            'import java.util.*;',
            'public class Main {',
            '    static int maxArea(int[] h) {',
            '        int l = 0, r = h.length - 1, best = 0;',
            '        while (l < r) {',
            '            best = Math.max(best, Math.min(h[l], h[r]) * (r - l));',
            '            if (h[l] < h[r]) l++;',
            '            else r--;',
            '        }',
            '        return best;',
            '    }',
            '    public static void main(String[] args) {',
            '        int[] h = {1, 8, 6, 2, 5, 4, 8, 3, 7};',
            '        System.out.println(maxArea(h));',
            '    }',
            '}',
