            '##4## Two pointers and best area. [Variables](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/variables.html)',
            '##5## Loop until pointers meet. [while](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/while.html)',
