            'void main() {',
            '  var h = [1, 8, 6, 2, 5, 4, 8, 3, 7];',
            '  var l = 0, r = h.length - 1, best = 0;',
            '  while (l < r) {',
            '    var area = (h[l] < h[r] ? h[l] : h[r]) * (r - l);',
            '    if (area > best) best = area;',
            '    if (h[l] < h[r]) l++;',
            '    else r--;',
