            '~~~problem',
            'title: Maximum Product Subarray',
            'difficulty: medium',
            'source: LeetCode 152 · Amazon, Microsoft',
            'tags: array, dp, kadane-variant',
            'statement: Largest product of a contiguous subarray.',
            'approach: Track both max and min ending at each position, because a negative times a negative is positive. Swap them when `nums[i] < 0`. This is Kadane with two states.',
            'time: O(n)',
            'space: O(1)',
            'solution: maxprodsubarray',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: maxprodsubarray',
            '#include <stdio.h>',
            'int maxProduct(int* nums, int n) {',
            '    int maxEnd = nums[0], minEnd = nums[0], result = nums[0];',
            '    for (int i = 1; i < n; i++) {',
            '        int temp = maxEnd;',
            '        if (nums[i] < 0) { maxEnd = minEnd; minEnd = temp; }',
            '        maxEnd = nums[i] > maxEnd * nums[i] ? nums[i] : maxEnd * nums[i];',
            '        minEnd = nums[i] < minEnd * nums[i] ? nums[i] : minEnd * nums[i];',
            '        if (maxEnd > result) result = maxEnd;',
            '    }',
            '    return result;',
            '}',
            'int main() {',
            '    int nums[] = {2, 3, -2, 4};',
            '    int n = 4;',
            '    printf("%d\\n", maxProduct(nums, n));',
            '    return 0;',
            '}',
            '---',
            '##1## Standard I/O header. [stdio]({c:stdio})',
            '##2## Function returns max product. [Functions](https://www.learn-c.org/en/Functions)',
            '##3## Track max/min ending here and global result. [Variables](https://www.learn-c.org/en/Variables)',
            '##4## Scan from second element. [For loops]({c:for})',
            '##5## Save maxEnd before swap. [Variables](https://www.learn-c.org/en/Variables)',
            '##6## Negative flips max/min roles. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##7## Update max ending here. [Variables](https://www.learn-c.org/en/Variables)',
            '##8## Update min ending here. [Variables](https://www.learn-c.org/en/Variables)',
            '##9## Update global best. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##11## Return result. [return]({c:return})',
            '##12## Entry point. [main]({c:main})',
            '##14## Print result. [printf]({c:printf})',
            '##15## Exit successfully. [return]({c:return})',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: maxprodsubarray',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int maxProduct(vector<int>& nums) {',
            '    int maxEnd = nums[0], minEnd = nums[0], result = nums[0];',
            '    for (int i = 1; i < nums.size(); i++) {',
            '        if (nums[i] < 0) swap(maxEnd, minEnd);',
            '        maxEnd = max(nums[i], maxEnd * nums[i]);',
            '        minEnd = min(nums[i], minEnd * nums[i]);',
            '        result = max(result, maxEnd);',
            '    }',
            '    return result;',
            '}',
            'int main() {',
            '    vector<int> nums = {2, 3, -2, 4};',
            '    cout << maxProduct(nums) << "\\n";',
            '    return 0;',
            '}',
            '---',
