            '##9## Update global best. [max]({cpp:max})',
            '##11## Return result. [return](https://en.cppreference.com/w/cpp/language/return)',
            '##12## Entry point. [main]({cpp:main})',
            '##13## Print result. [cout]({cpp:cout})',
