            '~~~explain',
            'lang: dart',
            'group: maxprodsubarray',
            'void main() {',
            '  var nums = [2, 3, -2, 4];',
            '  var maxEnd = nums[0], minEnd = nums[0], result = nums[0];',
            '  for (var i = 1; i < nums.length; i++) {',
            '    if (nums[i] < 0) { var t = maxEnd; maxEnd = minEnd; minEnd = t; }',
            '    maxEnd = [nums[i], maxEnd * nums[i]].reduce((a, b) => a > b ? a : b);',
            '    minEnd = [nums[i], minEnd * nums[i]].reduce((a, b) => a < b ? a : b);',
            '    if (maxEnd > result) result = maxEnd;',
            '  }',
            '  print(result);',
            '}',
