            '##5## Pattern longer than string. [If statements](https://en.cppreference.com/w/cpp/language/if)',
            '##6## Frequency diff array. [vector]({cpp:vector})',
            '##7## Build diff for first window. [For loops](https://en.cppreference.com/w/cpp/language/for)',
            '##11## Count non-zero diffs. [count_if](https://en.cppreference.com/w/cpp/algorithm/count_if)',
            '##12## First window is anagram. [push_back](https://en.cppreference.com/w/cpp/container/vector/push_back)',
            '##13## Slide window. [For loops](https://en.cppreference.com/w/cpp/language/for)',
            '##20## Check if anagram. [push_back](https://en.cppreference.com/w/cpp/container/vector/push_back)',
            '##22## Return result. [return](https://en.cppreference.com/w/cpp/language/return)',
            '##23## Entry point. [main]({cpp:main})',
            '##24## Print indices. [for](https://en.cppreference.com/w/cpp/language/range-for)',
            '##26## Success exit. [return](https://en.cppreference.com/w/cpp/language/return)',
