            '~~~explain',
            'lang: java',
            'group: findanagrams',
            'import java.util.*;',
            'public class Main {',
            '    static List<Integer> findAnagrams(String s, String p) {',
            '        List<Integer> result = new ArrayList<>();',
            '        if (s.length() < p.length()) return result;',
            '        int[] freq = new int[26];',
            '        for (int i = 0; i < p.length(); i++) {',
            '            freq[p.charAt(i) - \'a\']++;',
            '            freq[s.charAt(i) - \'a\']--;',
            '        }',
            '        int diff = 0;',
            '        for (int x : freq) if (x != 0) diff++;',
            '        if (diff == 0) result.add(0);',
            '        for (int i = p.length(); i < s.length(); i++) {',
            '            if (freq[s.charAt(i) - \'a\'] == 0) diff++;',
            '            freq[s.charAt(i) - \'a\']--;',
            '            if (freq[s.charAt(i) - \'a\'] == 0) diff--;',
            '            if (freq[s.charAt(i - p.length()) - \'a\'] == 0) diff++;',
            '            freq[s.charAt(i - p.length()) - \'a\']++;',
            '            if (freq[s.charAt(i - p.length()) - \'a\'] == 0) diff--;',
            '            if (diff == 0) result.add(i - p.length() + 1);',
            '        }',
            '        return result;',
            '    }',
            '    public static void main(String[] args) {',
            '        System.out.println(findAnagrams("cbaebabacd", "abc"));',
            '    }',
            '}',
            '---',
            '##1## Imports utility classes. [import]({java:import})',
            '##2## All methods live in a class. [class]({java:class})',
            '##3## Static method returns indices. [static](https://docs.oracle.com/javase/tutorial/java/javaOO/classvariables.html)',
            '##4## Result list. [ArrayList](https://docs.oracle.com/javase/8/docs/api/java/util/ArrayList.html)',
            '##5## Pattern longer check. [if]({java:if})',
            '##6## Frequency diff array. [Arrays](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/arrays.html)',
            '##7## Build diff for first window. [for]({java:for})',
            '##12## Count non-zero diffs. [for]({java:for})',
            '##14## First window is anagram. [List.add](https://docs.oracle.com/javase/8/docs/api/java/util/List.html)',
            '##15## Slide window. [for]({java:for})',
            '##22## Check if anagram. [List.add](https://docs.oracle.com/javase/8/docs/api/java/util/List.html)',
            '##24## Return result. [return]({java:return})',
