            '~~~explain',
            'lang: python',
            'group: findanagrams',
            'def main():',
            '    s, p = "cbaebabacd", "abc"',
            '    result = []',
            '    if len(s) < len(p): print(result); return',
            '    freq = [0] * 26',
            '    for i in range(len(p)):',
            '        freq[ord(p[i]) - ord("a")] += 1',
            '        freq[ord(s[i]) - ord("a")] -= 1',
            '    diff = sum(1 for x in freq if x != 0)',
            '    if diff == 0: result.append(0)',
            '    for i in range(len(p), len(s)):',
            '        if freq[ord(s[i]) - ord("a")] == 0: diff += 1',
            '        freq[ord(s[i]) - ord("a")] -= 1',
            '        if freq[ord(s[i]) - ord("a")] == 0: diff -= 1',
            '        if freq[ord(s[i - len(p)]) - ord("a")] == 0: diff += 1',
            '        freq[ord(s[i - len(p)]) - ord("a")] += 1',
            '        if freq[ord(s[i - len(p)]) - ord("a")] == 0: diff -= 1',
            '        if diff == 0: result.append(i - len(p) + 1)',
            '    print(result)',
            '',
            'main()',
            '---',
