            '##4## Pattern longer check. [if]({python:if})',
            '##5## Frequency diff array. [list]({python:list})',
            '##6## Build diff for first window. [range]({python:range})',
            '##10## Count non-zero diffs. [sum](https://docs.python.org/3/library/functions.html#sum)',
            '##11## First window is anagram. [list]({python:list})',
            '##12## Slide window. [range]({python:range})',
            '##18## Check if anagram. [list]({python:list})',
            '##20## Print result. [print]({python:print})',
            '~~~',
