            '~~~explain',
            'lang: dart',
            'group: findanagrams',
            'void main() {',
            '  var s = "cbaebabacd", p = "abc";',
            '  var result = <int>[];',
            '  if (s.length < p.length) { print(result); return; }',
            '  var freq = List.filled(26, 0);',
            '  for (var i = 0; i < p.length; i++) {',
            '    freq[p.codeUnitAt(i) - 97]++;',
            '    freq[s.codeUnitAt(i) - 97]--;',
            '  }',
            '  var diff = freq.where((x) => x != 0).length;',
            '  if (diff == 0) result.add(0);',
            '  for (var i = p.length; i < s.length; i++) {',
            '    if (freq[s.codeUnitAt(i) - 97] == 0) diff++;',
            '    freq[s.codeUnitAt(i) - 97]--;',
            '    if (freq[s.codeUnitAt(i) - 97] == 0) diff--;',
            '    if (freq[s.codeUnitAt(i - p.length) - 97] == 0) diff++;',
            '    freq[s.codeUnitAt(i - p.length) - 97]++;',
            '    if (freq[s.codeUnitAt(i - p.length) - 97] == 0) diff--;',
            '    if (diff == 0) result.add(i - p.length + 1);',
            '  }',
            '  print(result);',
            '}',
            '---',
            '##1## Dart entry point. [main]({dart:main})',
            '##2## Input strings. [String](https://api.dart.dev/stable/dart-core/String-class.html)',
            '##3## Result list. [List]({dart:List})',
            '##4## Pattern longer check. [if]({dart:if})',
            '##5## Frequency diff array. [List]({dart:List})',
            '##6## Build diff for first window. [for]({dart:for})',
            '##10## Count non-zero diffs. [where](https://api.dart.dev/stable/dart-core/Iterable-class.html#method-where)',
            '##11## First window is anagram. [List]({dart:List})',
            '##12## Slide window. [for]({dart:for})',
            '##18## Check if anagram. [List]({dart:List})',
            '##20## Print result. [print]({dart:print})',
            '~~~',
