            '~~~problem',
            'title: Two Sum II — Input Array Is Sorted',
            'difficulty: medium',
            'source: LeetCode 167 · Bloomberg, Amazon',
            'tags: array, two-pointers, sorted',
            'statement: Given a sorted array (1-indexed), find two indices whose values add up to `target`.',
            'approach: Follow-up to Two Sum but the array is already sorted — so two pointers at both ends replace the hashmap. If `numbers[l] + numbers[r]` is too small, advance `l`; if too big, pull `r` back. Each element is visited at most once.',
            'time: O(n)',
            'space: O(1)',
            'solution: twosum2',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: twosum2',
            '#include <stdio.h>',
            'int main() {',
            '    int numbers[] = {2, 7, 11, 15};',
            '    int target = 9;',
            '    int n = 4;',
            '    int l = 0, r = n - 1;',
            '    while (l < r) {',
            '        int sum = numbers[l] + numbers[r];',
            '        if (sum == target) {',
            '            printf("%d %d\\n", l + 1, r + 1);',
            '            return 0;',
            '        }',
            '        if (sum < target) l++;',
            '        else r--;',
            '    }',
            '    return 1;',
            '}',
            '---',
            '##1## Standard I/O header for `printf`. [stdio]({c:stdio})',
            '##2## Program entry point. [main]({c:main})',
            '##3## Sorted input array. [Arrays]({c:array})',
            '##4## The sum we are hunting for. [Variables](https://www.learn-c.org/en/Variables)',
            '##5## Length, tracked by hand in C. [Variables](https://www.learn-c.org/en/Variables)',
            '##6## Two pointers from the two ends. [Variables](https://www.learn-c.org/en/Variables)',
            '##7## Loop until the pointers meet. [while]({c:while})',
            '##8## Sum of the two endpoints. [Variables](https://www.learn-c.org/en/Variables)',
            '##9## Exact match found. [if]({c:if})',
            '##10## Print 1-based indices (problem requirement). [printf]({c:printf})',
            '##11## Success exit. [return]({c:return})',
            '##13## Sum too small, move left pointer right. [if]({c:if})',
            '##14## Sum too big, pull right pointer left. [if]({c:if})',
            '##16## No pair found, signal failure. [return]({c:return})',
            '~~~',
            '',
            '~~~explain',
