            '~~~explain',
            'lang: dart',
            'group: twosum2',
            'void main() {',
            '  var numbers = [2, 7, 11, 15];',
            '  var t = 9;',
            '  var l = 0, r = numbers.length - 1;',
            '  while (l < r) {',
            '    var s = numbers[l] + numbers[r];',
            '    if (s == t) {',
            '      print(\'${l + 1} ${r + 1}\');',
            '      return;',
            '    }',
            '    if (s < t) {',
            '      l++;',
            '    } else {',
            '      r--;',
            '    }',
            '  }',
            '}',
            '---',
            '##1## Dart entry point. [main]({dart:main})',
            '##2## Sorted input list. [List]({dart:List})',
            '##3## Target sum. [var]({dart:var})',
            '##4## Pointers from both ends. [var]({dart:var})',
            '##5## Sweep loop. [while]({dart:while})',
