            '~~~problem',
            'title: Rotate Array',
            'difficulty: medium',
            'source: LeetCode 189 · Microsoft, Facebook',
            'tags: array, reversal, rotation',
            'statement: Rotate `nums` to the right by `k` steps, in place.',
            'approach: Reversal rotation lemma — reverse the whole array, then reverse `[0, k-1]` and `[k, n-1]`. After three reversals the array is rotated right by `k`. Works because reversing the tail unhooks it to the front.',
            'time: O(n)',
            'space: O(1)',
            'solution: rotatearray',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: rotatearray',
            '#include <stdio.h>',
            'void reverse(int a[], int n) {',
            '    for (int l = 0, r = n - 1; l < r; l++, r--) {',
            '        int t = a[l]; a[l] = a[r]; a[r] = t;',
            '    }',
            '}',
            'int main() {',
            '    int a[] = {1, 2, 3, 4, 5, 6, 7};',
            '    int n = 7, k = 3;',
            '    k %= n;',
            '    reverse(a, n);',
            '    reverse(a, k);',
            '    reverse(a + k, n - k);',
            '    for (int i = 0; i < n; i++) printf("%d ", a[i]);',
            '    printf("\\n");',
            '    return 0;',
            '}',
            '---',
            '##1## Standard I/O header. [stdio]({c:stdio})',
            '##2## Helper reverses a subarray in place. [Functions](https://www.learn-c.org/en/Functions)',
            '##3## Two pointers swap inward. [for]({c:for})',
            '##4## Swap pair. [Variables]({c:pointer})',
            '##6## Entry point. [main]({c:main})',
            '##7## Input data. [Arrays]({c:array})',
            '##8## Size and steps. [Variables](https://www.learn-c.org/en/Variables)',
            '##9## k > n wrap-around. [Variables](https://www.learn-c.org/en/Variables)',
            '##10## Reverse everything. [Functions](https://www.learn-c.org/en/Functions)',
            '##11## Reverse the first k. [Functions](https://www.learn-c.org/en/Functions)',
            '##12## Reverse the tail of size n-k. [Functions](https://www.learn-c.org/en/Functions)',
            '##13## Print the rotated array. [for]({c:for})',
            '##14## Trailing newline. [printf]({c:printf})',
            '##15## Success exit. [return]({c:return})',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: rotatearray',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int main() {',
            '    vector<int> a = {1, 2, 3, 4, 5, 6, 7};',
            '    int k = 3;',
            '    k %= (int)a.size();',
            '    reverse(a.begin(), a.end());',
            '    reverse(a.begin(), a.begin() + k);',
            '    reverse(a.begin() + k, a.end());',
            '    for (int x : a) cout << x << " ";',
