            '~~~explain',
            'lang: java',
            'group: rotatearray',
            'import java.util.*;',
            'public class Main {',
            '    static void reverse(int[] a, int l, int r) {',
            '        while (l < r) {',
            '            int t = a[l]; a[l] = a[r]; a[r] = t;',
            '            l++; r--;',
            '        }',
            '    }',
            '    public static void main(String[] args) {',
            '        int[] a = {1, 2, 3, 4, 5, 6, 7};',
            '        int k = 3;',
