            '~~~problem',
            'title: Product of Array Except Self',
            'difficulty: medium',
            'source: LeetCode 238 · Amazon, Facebook, Apple',
            'tags: array, prefix-product, prefix-sum',
            'statement: Return an array `answer[i]` = product of all elements except `nums[i]`, without using division.',
            'solution: productexceptself',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: productexceptself',
            '#include <stdio.h>',
            'int main() {',
            '    int a[] = {1, 2, 3, 4};',
            '    int n = 4;',
            '    int out[4];',
            '    int lp = 1;',
            '    for (int i = 0; i < n; i++) { out[i] = lp; lp *= a[i]; }',
            '    int rp = 1;',
            '    for (int i = n - 1; i >= 0; i--) { out[i] *= rp; rp *= a[i]; }',
            '    for (int i = 0; i < n; i++) printf("%d ", out[i]);',
            '    printf("\\n");',
            '    return 0;',
            '}',
            '---',
            '##1## Standard I/O header. [stdio]({c:stdio})',
            '##2## Entry point. [main]({c:main})',
            '##3## Input data. [Arrays]({c:array})',
            '##4## Array size. [Variables](https://www.learn-c.org/en/Variables)',
            '##5## Result array. [Arrays]({c:array})',
            '##6## Running left product. [Variables](https://www.learn-c.org/en/Variables)',
            '##7## Forward pass: left-product of everything before `i`. [for]({c:for})',
            '##8## Running right product. [Variables](https://www.learn-c.org/en/Variables)',
            '##9## Backward pass multiplies in the right side. [for]({c:for})',
            '##10## Print the result. [for]({c:for})',
            '##11## Newline. [printf]({c:printf})',
            '##12## Success exit. [return]({c:return})',
            '~~~',
