            '##1## [dartio]({dart:dartio}) supplies the standard input library.',
            '##2## [main]({dart:main}) is the Dart entry point.',
            '##3## [stdin]({dart:stdin}).[readLineSync]({dart:readLineSync}) reads the line and the cascade [sort]({dart:sort}) orders it in place.',
            '##4## [length]({dart:length}) is the number of elements.',
            '##5## [for]({dart:for}) fixes each possible first index.',
            '##6## [if]({dart:if}) skips duplicate first values.',
            '##8## The [while](https://dart.dev/language/loops) loop scans for the pair.',
            '##10## [if]({dart:if}) detects a zero-sum triplet.',
            '##11## [print]({dart:print}) writes the three values on one line.',
            '##12## Equal lo values are skipped with a [while](https://dart.dev/language/loops) scan to avoid duplicate triplets.',
            '##16## elif advances lo when the sum needs to grow, an [if]({dart:if}) branch.',
