            '~~~problem',
            'title: "153. Find Minimum in Rotated Sorted Array"',
            'difficulty: medium',
            'source: LeetCode 153 · Microsoft, Amazon, Apple',
            'tags: array, binary search',
            'statement: Given a rotated sorted array of distinct integers, find the minimum element in the array.',
            'approach: Binary search locates the single descending break in the rotation. If the middle value is greater than the rightmost value the minimum lies in the right half, otherwise it is at mid or in the left half. Each step discards half the range, giving O(log n) time with O(1) space.',
            'time: O(log n)',
            'space: O(1)',
            'solution: findminrotated',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: findminrotated',
            '#include <stdio.h>',
            'int findMin(int* nums, int n) {',
            '    int lo = 0, hi = n - 1;',
            '    while (lo < hi) {',
            '        int mid = lo + (hi - lo) / 2;',
            '        if (nums[mid] > nums[hi]) {',
            '            lo = mid + 1;',
            '        } else {',
            '            hi = mid;',
            '        }',
            '    }',
            '    return nums[lo];',
            '}',
            'int main() {',
            '    int nums[] = {3, 4, 5, 1, 2};',
            '    int n = sizeof(nums) / sizeof(nums[0]);',
            '    printf("%d\\n", findMin(nums, n));',
            '    return 0;',
            '}',
            '---',
            '##2## The function findMin narrows the search over the [c:array]({c:array}) holding the rotated numbers.',
            '##3## lo and hi bound the current search range, with hi starting at n - 1. [ref](https://en.wikipedia.org/wiki/Binary_search_algorithm)',
            '##4## The [c:while]({c:while}) loop runs until the range collapses to one element.',
            '##5## mid splits the range safely with lo + (hi - lo) / 2, avoiding overflow. [ref](https://en.wikipedia.org/wiki/Binary_search_algorithm)',
            '##6## [c:if]({c:if}) the middle value exceeds the rightmost value, the break is to the right.',
            '##7## Move lo past mid to search the right segment. [ref](https://en.wikipedia.org/wiki/Binary_search_algorithm)',
            '##9## Otherwise keep mid by setting hi = mid, since it may be the minimum. [ref](https://en.wikipedia.org/wiki/Binary_search_algorithm)',
            '##12## [c:return]({c:return}) nums[lo], the element sitting at the rotation break.',
            '##14## [c:main]({c:main}) is the entry point that runs the sample case.',
            '##16## [c:sizeof]({c:sizeof}) divides by the element size to count elements.',
            '##17## [c:printf]({c:printf}) prints the minimum found by binary search.',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: findminrotated',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int findMin(vector<int>& nums) {',
            '    int lo = 0, hi = nums.size() - 1;',
            '    while (lo < hi) {',
            '        int mid = lo + (hi - lo) / 2;',
            '        if (nums[mid] > nums[hi]) {',
            '            lo = mid + 1;',
            '        } else {',
            '            hi = mid;',
            '        }',
            '    }',
            '    return nums[lo];',
            '}',
            'int main() {',
            '    vector<int> nums = {3, 4, 5, 1, 2};',
            '    cout << findMin(nums) << "\\n";',
            '    return 0;',
            '}',
            '---',
            '##1## Includes the bundled standard [header](https://en.cppreference.com/w/cpp/header) bits/stdc++.h.',
            '##2## [cpp:namespace]({cpp:namespace}) std enables unqualified standard names.',
            '##3## The solver receives the numbers by reference as a [cpp:vector]({cpp:vector}).',
            '##5## The [while loop](https://en.cppreference.com/w/cpp/language/while) halves the search range each pass.',
            '##6## mid is computed to avoid overflow. [ref](https://en.wikipedia.org/wiki/Binary_search_algorithm)',
            '##7## The [if statement](https://en.cppreference.com/w/cpp/language/if) checks the middle against the right end.',
            '##8## Move lo past mid to the right segment. [ref](https://en.wikipedia.org/wiki/Binary_search_algorithm)',
            '##10## Otherwise hi moves down to mid to preserve the candidate. [ref](https://en.wikipedia.org/wiki/Binary_search_algorithm)',
            '##13## The [return statement](https://en.cppreference.com/w/cpp/language/return) yields the minimum at lo.',
            '##15## [cpp:main]({cpp:main}) is the program entry point.',
            '##16## Build the input [cpp:vector]({cpp:vector}) with the rotated array.',
            '##17## [cpp:cout]({cpp:cout}) prints the result to standard output.',
            '~~~',
            '',
            '~~~explain',
            'lang: java',
            'group: findminrotated',
            'import java.util.*;',
            'class Main {',
            '    public static int findMin(int[] nums) {',
            '        int lo = 0, hi = nums.length - 1;',
            '        while (lo < hi) {',
            '            int mid = lo + (hi - lo) / 2;',
            '            if (nums[mid] > nums[hi]) {',
            '                lo = mid + 1;',
            '            } else {',
            '                hi = mid;',
            '            }',
            '        }',
            '        return nums[lo];',
            '    }',
            '    public static void main(String[] args) {',
            '        Scanner sc = new Scanner(System.in);',
            '        int[] nums = {3, 4, 5, 1, 2};',
            '        System.out.print(findMin(nums));',
            '    }',
            '}',
            '---',
            '##1## [java:import]({java:import}) java.util.* makes Scanner available.',
            '##2## [java:class]({java:class}) Main hosts the static solution method.',
            '##4## lo and hi bound the search over the input [array](https://docs.oracle.com/javase/8/docs/api/java/util/Arrays.html).',
            '##5## The [while loop](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/while.html) narrows the range.',
            '##6## mid avoids overflow via lo + (hi - lo) / 2. [ref](https://en.wikipedia.org/wiki/Binary_search_algorithm)',
            '##7## [java:if]({java:if}) the middle element is greater than the right end, the break is right.',
            '##8## Discard the left half by moving lo past mid. [ref](https://en.wikipedia.org/wiki/Binary_search_algorithm)',
            '##10## Otherwise collapse hi onto mid. [ref](https://en.wikipedia.org/wiki/Binary_search_algorithm)',
            '##13## [java:return]({java:return}) the minimum element at index lo.',
            '##15## [java:main]({java:main}) is the JVM entry point.',
            '##16## [java:scanner]({java:scanner}) is created to read from standard input.',
            '##18## [java:System]({java:System}).out.print writes the answer.',
