            '##9## Otherwise keep mid by moving hi down. [ref](https://en.wikipedia.org/wiki/Binary_search_algorithm)',
            '##10## [return](https://docs.python.org/3/reference/simple_stmts.html#the-return-statement) the element at lo.',
