            '~~~problem',
            'title: "128. Longest Consecutive Sequence"',
            'difficulty: medium',
            'source: LeetCode 128 · Amazon, Meta, Google',
            'tags: array, hash set',
            'statement: Given an unsorted array of integers, find the length of the longest run of consecutive numbers.',
            'approach: Insert all numbers into a hash set, then count each streak only from its smallest value, that is, only when x - 1 is absent. Each number is visited a constant number of times, so the total time is O(n) with O(n) extra space for the set.',
            'time: O(n)',
            'space: O(n)',
            'solution: longestconsecutive',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: longestconsecutive',
            '#include <stdio.h>',
            '#define SIZE 4096',
            'int table[SIZE];',
            'void insert(int x) {',
            '    int i = (x & 0x7fffffff) % SIZE;',
            '    while (table[i] != 0 && table[i] != x) i = (i + 1) % SIZE;',
            '    table[i] = x;',
            '}',
            'int contains(int x) {',
            '    int i = (x & 0x7fffffff) % SIZE;',
            '    while (table[i] != 0) {',
            '        if (table[i] == x) return 1;',
            '        i = (i + 1) % SIZE;',
            '    }',
            '    return 0;',
            '}',
            'int main() {',
            '    int nums[] = {100, 4, 200, 1, 3, 2};',
            '    int n = sizeof(nums) / sizeof(nums[0]);',
            '    int best = 0;',
            '    for (int i = 0; i < n; i++) insert(nums[i]);',
            '    for (int i = 0; i < n; i++) {',
            '        int x = nums[i];',
            '        if (contains(x - 1)) continue;',
            '        int len = 0;',
            '        while (contains(x + len)) len++;',
            '        if (len > best) best = len;',
            '    }',
            '    printf("%d\\n", best);',
            '    return 0;',
            '}',
            '---',
            '##3## The hash set is a global [c:array]({c:array}) using open addressing.',
            '##5## The bucket index derives from the key with a bit mask and modulo. [hash table](https://en.wikipedia.org/wiki/Hash_table)',
            '##6## Linear probing walks to the next free slot in the [c:while]({c:while}) loop.',
            '##7## Store the value in the chosen bucket. [ref](https://en.wikipedia.org/wiki/Hash_table)',
            '##12## [c:if]({c:if}) the bucket holds the key, the set contains it.',
            '##17## [c:main]({c:main}) runs the driver logic.',
            '##19## [c:sizeof]({c:sizeof}) computes the element count of the array.',
            '##21## Insert every number into the hash set. [ref](https://en.wikipedia.org/wiki/Hash_table)',
            '##24## Only count from a value whose left neighbor is absent. [problem page](https://leetcode.com/problems/longest-consecutive-sequence/)',
            '##26## The [c:while]({c:while}) loop extends the streak while consecutive values exist.',
            '##29## [c:printf]({c:printf}) prints the longest streak length.',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: longestconsecutive',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int longestConsecutive(vector<int>& nums) {',
            '    unordered_set<int> s(nums.begin(), nums.end());',
            '    int best = 0;',
            '    for (auto x : nums) {',
            '        if (s.count(x - 1)) continue;',
            '        int len = 1;',
            '        while (s.count(x + len)) len++;',
            '        best = max(best, len);',
            '    }',
            '    return best;',
            '}',
            'int main() {',
            '    vector<int> nums = {100, 4, 200, 1, 3, 2};',
            '    cout << longestConsecutive(nums) << "\\n";',
            '    return 0;',
            '}',
            '---',
            '##1## Includes the standard [header](https://en.cppreference.com/w/cpp/header) bundle.',
            '##2## [cpp:namespace]({cpp:namespace}) std allows unqualified names.',
            '##3## The solver takes the input as a [cpp:vector]({cpp:vector}) reference.',
            '##4## Copy the values into a hash set for O(1) lookups. [unordered_set](https://en.cppreference.com/w/cpp/container/unordered_set)',
            '##6## [cpp:auto]({cpp:auto}) deduces the element type in the range loop.',
            '##7## Values with a left neighbor are not sequence starts. [ref](https://leetcode.com/problems/longest-consecutive-sequence/)',
            '##9## The [while loop](https://en.cppreference.com/w/cpp/language/while) grows the streak rightward.',
            '##10## [cpp:max]({cpp:max}) keeps the best length found so far.',
            '##12## The [return statement](https://en.cppreference.com/w/cpp/language/return) yields the answer.',
            '##14## [cpp:main]({cpp:main}) is the entry point.',
            '##15## Build the sample [cpp:vector]({cpp:vector}).',
            '##16## [cpp:cout]({cpp:cout}) prints the result.',
            '~~~',
            '',
            '~~~explain',
            'lang: java',
            'group: longestconsecutive',
            'import java.util.*;',
            'class Main {',
            '    public static int longestConsecutive(int[] nums) {',
            '        Set<Integer> s = new HashSet<>();',
            '        for (int x : nums) s.add(x);',
            '        int best = 0;',
            '        for (int x : nums) {',
            '            if (s.contains(x - 1)) continue;',
            '            int len = 1;',
            '            while (s.contains(x + len)) len++;',
            '            best = Math.max(best, len);',
            '        }',
            '        return best;',
            '    }',
            '    public static void main(String[] args) {',
            '        Scanner sc = new Scanner(System.in);',
            '        int[] nums = {100, 4, 200, 1, 3, 2};',
            '        System.out.print(longestConsecutive(nums));',
            '    }',
            '}',
            '---',
            '##1## [java:import]({java:import}) java.util.* supplies HashSet and Scanner.',
            '##2## [java:class]({java:class}) Main hosts the static method.',
            '##4## [java:HashSet]({java:HashSet}) provides O(1) membership tests.',
            '##5## The [java:for]({java:for}) loop adds every number to the set.',
            '##8## Only a value without x - 1 can start a sequence. [ref](https://leetcode.com/problems/longest-consecutive-sequence/)',
            '##10## The [while loop](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/while.html) extends the consecutive run.',
            '##11## [java:Math]({java:Math}).max tracks the longest streak.',
            '##13## [java:return]({java:return}) the maximum length.',
            '##15## [java:main]({java:main}) is the JVM entry point.',
            '##16## [java:scanner]({java:scanner}) reads from standard input.',
            '##18## [java:System]({java:System}).out.print writes the answer.',
            '~~~',
            '',
            '~~~explain',
            'lang: python',
            'group: longestconsecutive',
            'def longestConsecutive(nums):',
            '    s = set(nums)',
            '    best = 0',
            '    for x in nums:',
            '        if x - 1 in s:',
            '            continue',
            '        length = 1',
            '        while x + length in s:',
            '            length += 1',
            '        best = max(best, length)',
            '    return best',
            'def main():',
            '    nums = [100, 4, 200, 1, 3, 2]',
            '    print(longestConsecutive(nums))',
            'main()',
            '---',
            '##1## [python:def]({python:def})ines the solver taking a [python:list]({python:list}).',
            '##2## Build a [python:set]({python:set}) from the list for O(1) lookups.',
            '##4## [python:for]({python:for}) visits every element exactly once.',
            '##5## [python:if]({python:if}) x - 1 exists, x cannot start a streak.',
            '##8## The [while loop](https://docs.python.org/3/reference/compound_stmts.html) counts forward while values are consecutive.',
            '##10## [python:max]({python:max}) keeps the longest run seen.',
            '##11## [return](https://docs.python.org/3/reference/simple_stmts.html#the-return-statement) the best streak length.',
            '##12## [python:def]({python:def})ines main, the driver.',
            '##13## Build the sample [python:list]({python:list}).',
            '##14## [python:print]({python:print}) outputs the result.',
            '##15## Calling [python:main]({python:main}) runs the program.',
            '~~~',
