            '~~~explain',
            'lang: dart',
            'group: longestconsecutive',
            'import \'dart:io\';',
            'int longestConsecutive(List<int> nums) {',
            '  Set<int> s = Set.from(nums);',
            '  int best = 0;',
            '  for (int x in nums) {',
            '    if (s.contains(x - 1)) continue;',
            '    int length = 1;',
            '    while (s.contains(x + length)) length++;',
            '    if (length > best) best = length;',
            '  }',
            '  return best;',
            '}',
            'void main() {',
            '  List<int> nums = [100, 4, 200, 1, 3, 2];',
            '  print(longestConsecutive(nums));',
            '}',
            '---',
            '##1## Import [dart:dartio]({dart:dartio}) for console access.',
            '##2## The function works over a [dart:List]({dart:List}) of integers.',
            '##3## Build a [dart:Set]({dart:Set}) for O(1) membership checks.',
            '##5## The [dart:forin]({dart:forin}) loop visits each element.',
            '##6## [dart:if]({dart:if}) a left neighbor exists, the value is not a start.',
            '##8## The [dart:while]({dart:while}) loop extends the consecutive run.',
            '##9## Update best when the current run is longer. [ref](https://dart.dev/guides/language/language-tour)',
