            '~~~problem',
            'title: "209. Minimum Size Subarray Sum"',
            'difficulty: medium',
            'source: LeetCode 209 · Facebook, Amazon, Google',
            'tags: array, sliding window, two pointers',
            'statement: Given an array of positive integers and a target sum, find the minimal length of a contiguous subarray whose sum is at least target, or 0 if none exists.',
            'approach: A sliding window expands right while growing the sum, then shrinks left whenever the sum reaches the target, tracking the smallest window length found. Each element enters and leaves the window once, giving O(n) time and O(1) extra space.',
            'time: O(n)',
            'space: O(1)',
            'solution: minsizesubarray',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: minsizesubarray',
            '#include <stdio.h>',
            'int minSubArrayLen(int target, int* nums, int n) {',
            '    int left = 0, sum = 0, best = n + 1;',
            '    for (int right = 0; right < n; right++) {',
            '        sum += nums[right];',
            '        while (sum >= target) {',
            '            if (right - left + 1 < best) best = right - left + 1;',
            '            sum -= nums[left];',
            '            left++;',
            '        }',
            '    }',
            '    return best == n + 1 ? 0 : best;',
            '}',
            'int main() {',
            '    int target = 7;',
            '    int nums[] = {2, 3, 1, 2, 4, 3};',
            '    int n = sizeof(nums) / sizeof(nums[0]);',
            '    printf("%d\\n", minSubArrayLen(target, nums, n));',
            '    return 0;',
            '}',
            '---',
            '##2## The function slides a window over the [c:array]({c:array}) of positive integers.',
            '##3## left is the window start and best acts as an infinity sentinel. [sliding window](https://en.wikipedia.org/wiki/Sliding_window_protocol)',
            '##4## The [c:for]({c:for}) loop extends the window with right as the end.',
            '##6## The [c:while]({c:while}) loop shrinks the window while the sum is valid.',
            '##7## Record the smallest window that reaches the target. [ref](https://en.wikipedia.org/wiki/Maximum_subarray_problem)',
            '##8## Remove the leaving left value from the running sum. [ref](https://en.wikipedia.org/wiki/Sliding_window_protocol)',
            '##9## Advance left to close the window. [ref](https://en.wikipedia.org/wiki/Sliding_window_protocol)',
            '##12## [c:return]({c:return}) 0 when no window reached the target.',
            '##14## [c:main]({c:main}) is the entry point.',
            '##17## [c:sizeof]({c:sizeof}) computes the number of elements.',
            '##18## [c:printf]({c:printf}) prints the minimum subarray length.',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: minsizesubarray',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int minSubArrayLen(int target, vector<int>& nums) {',
            '    int left = 0, sum = 0, best = nums.size() + 1;',
            '    for (int right = 0; right < nums.size(); right++) {',
            '        sum += nums[right];',
            '        while (sum >= target) {',
            '            best = min(best, right - left + 1);',
            '            sum -= nums[left];',
            '            left++;',
            '        }',
            '    }',
            '    return best == (int)nums.size() + 1 ? 0 : best;',
            '}',
            'int main() {',
            '    int target = 7;',
            '    vector<int> nums = {2, 3, 1, 2, 4, 3};',
            '    cout << minSubArrayLen(target, nums) << "\\n";',
            '    return 0;',
            '}',
            '---',
            '##3## The function takes target and the [cpp:vector]({cpp:vector}) by reference.',
            '##4## best starts above the array size as a sentinel. [ref](https://en.cppreference.com/w/cpp/container/vector)',
            '##5## The [for loop](https://en.cppreference.com/w/cpp/language/for) grows the window to the right.',
            '##7## The [while loop](https://en.cppreference.com/w/cpp/language/while) contracts the window when valid.',
            '##8## [cpp:min]({cpp:min}) keeps the smallest valid window length.',
            '##9## Drop the outgoing left element from the sum. [ref](https://en.wikipedia.org/wiki/Sliding_window_protocol)',
            '##13## Return 0 when the target is never reached. [ref](https://en.cppreference.com/w/cpp/language/return)',
            '##15## [cpp:main]({cpp:main}) is the entry point.',
            '##16## target is the required subarray sum. [ref](https://en.cppreference.com/w/cpp/language/function)',
            '##17## Build the sample [cpp:vector]({cpp:vector}).',
            '##18## [cpp:cout]({cpp:cout}) prints the minimum length.',
            '~~~',
            '',
            '~~~explain',
            'lang: java',
            'group: minsizesubarray',
            'import java.util.*;',
            'class Main {',
            '    public static int minSubArrayLen(int target, int[] nums) {',
            '        int left = 0, sum = 0, best = nums.length + 1;',
            '        for (int right = 0; right < nums.length; right++) {',
            '            sum += nums[right];',
            '            while (sum >= target) {',
            '                best = Math.min(best, right - left + 1);',
            '                sum -= nums[left];',
            '                left++;',
            '            }',
            '        }',
            '        return best == nums.length + 1 ? 0 : best;',
            '    }',
            '    public static void main(String[] args) {',
            '        Scanner sc = new Scanner(System.in);',
            '        int target = 7;',
            '        int[] nums = {2, 3, 1, 2, 4, 3};',
            '        System.out.print(minSubArrayLen(target, nums));',
            '    }',
            '}',
            '---',
            '##2## [java:class]({java:class}) Main hosts the static method.',
            '##4## best holds the sentinel value beyond the array length. [ref](https://docs.oracle.com/javase/8/docs/api/java/util/Arrays.html)',
            '##5## The [java:for]({java:for}) loop advances the window end.',
            '##7## The [while loop](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/while.html) shrinks the window.',
            '##8## [java:Math]({java:Math}).min records the shortest window.',
            '##9## Subtract the value leaving the window from sum. [ref](https://en.wikipedia.org/wiki/Sliding_window_protocol)',
            '##13## [java:return]({java:return}) 0 when the target is unreachable.',
            '##15## [java:main]({java:main}) is the JVM entry point.',
            '##16## [java:scanner]({java:scanner}) reads from standard input.',
            '##18## Build the input [array](https://docs.oracle.com/javase/8/docs/api/java/util/Arrays.html).',
            '##19## [java:System]({java:System}).out.print outputs the answer.',
            '~~~',
            '',
            '~~~explain',
            'lang: python',
            'group: minsizesubarray',
            'def minSubArrayLen(target, nums):',
            '    left = 0',
            '    total = 0',
            '    best = len(nums) + 1',
            '    for right in range(len(nums)):',
            '        total += nums[right]',
            '        while total >= target:',
            '            best = min(best, right - left + 1)',
            '            total -= nums[left]',
            '            left += 1',
            '    return 0 if best == len(nums) + 1 else best',
            'def main():',
            '    target = 7',
            '    nums = [2, 3, 1, 2, 4, 3]',
            '    print(minSubArrayLen(target, nums))',
            'main()',
            '---',
            '##1## [python:def]({python:def})ines the sliding-window solver.',
            '##2## left marks the start of the current window. [ref](https://en.wikipedia.org/wiki/Sliding_window_protocol)',
            '##5## [python:for]({python:for}) with [python:range]({python:range}) iterates over window ends.',
            '##6## Extend the running total with the new right element. [ref](https://en.wikipedia.org/wiki/Sliding_window_protocol)',
            '##7## The [while loop](https://docs.python.org/3/reference/compound_stmts.html) shrinks while the total is valid.',
            '##8## [python:min]({python:min}) tracks the shortest valid window.',
            '##9## Subtract the value leaving the window. [ref](https://en.wikipedia.org/wiki/Sliding_window_protocol)',
            '##11## [return](https://docs.python.org/3/reference/simple_stmts.html#the-return-statement) 0 if no window reached the target.',
            '##12## [python:def]({python:def})ines main, the driver.',
            '##14## Build the sample [python:list]({python:list}).',
            '##15## [python:print]({python:print}) outputs the result.',
            '##16## Calling [python:main]({python:main}) runs the program.',
            '~~~',
            '',
            '~~~explain',
            'lang: dart',
            'group: minsizesubarray',
            'import \'dart:io\';',
            'int minSubArrayLen(int target, List<int> nums) {',
