            '~~~problem',
            'title: "287. Find the Duplicate Number"',
            'difficulty: medium',
            'source: LeetCode 287 · Amazon, Google, Microsoft',
            'tags: array, two pointers, cycle detection',
            'statement: Given an array of n+1 integers each in the range [1, n], find the single duplicate number without modifying the array and using only constant extra space.',
            'approach: Treat the array as a linked list where the value nums[i] points to the next index. Floyd\'s cycle detection finds the entry point of the cycle, which is exactly the duplicated number. This runs in O(n) time with O(1) extra space.',
            'time: O(n)',
            'space: O(1)',
            'solution: findduplicate',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: findduplicate',
            '#include <stdio.h>',
            'int findDuplicate(int* nums, int n) {',
            '    int slow = nums[0], fast = nums[0];',
            '    do {',
            '        slow = nums[slow];',
            '        fast = nums[nums[fast]];',
            '    } while (slow != fast);',
            '    slow = nums[0];',
            '    while (slow != fast) {',
            '        slow = nums[slow];',
            '        fast = nums[fast];',
            '    }',
            '    return slow;',
            '}',
            'int main() {',
            '    int a[] = {1, 3, 4, 2, 2};',
            '    int n = sizeof(a) / sizeof(a[0]);',
            '    printf("%d\\n", findDuplicate(a, n));',
            '    return 0;',
            '}',
            '---',
            '##2## The function treats each value as a pointer to the next index, forming a linked list via the [c:array]({c:array}) nums.',
            '##3## Two pointers start at the head; the [c:pointer]({c:pointer}) trick relies on indices mapping to values.',
            '##5## Slow advances one step with slow = nums[slow]. [Floyd\'s cycle detection](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##6## Fast advances two steps with fast = nums[nums[fast]]. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##7## The [c:while]({c:while}) loop runs until the two pointers meet inside the cycle.',
            '##9## Reset slow to the head so both walk from the cycle entry. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##10## This second [c:while]({c:while}) moves both one step at a time until they meet again.',
            '##13## [c:return]({c:return}) the entry point of the cycle, which is the duplicate number.',
            '##15## [c:main]({c:main}) defines the program entry point.',
            '##17## [c:sizeof]({c:sizeof}) computes the number of elements in the array.',
            '##18## [c:printf]({c:printf}) prints the duplicate found by the algorithm.',
            '##19## [c:return]({c:return}) 0 signals successful termination.',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: findduplicate',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int findDuplicate(vector<int>& nums) {',
            '    int slow = nums[0], fast = nums[0];',
            '    do {',
            '        slow = nums[slow];',
            '        fast = nums[nums[fast]];',
            '    } while (slow != fast);',
            '    slow = nums[0];',
            '    while (slow != fast) {',
            '        slow = nums[slow];',
            '        fast = nums[fast];',
            '    }',
            '    return slow;',
            '}',
            'int main() {',
            '    vector<int> nums = {1, 3, 4, 2, 2};',
            '    cout << findDuplicate(nums) << "\\n";',
            '    return 0;',
            '}',
            '---',
            '##3## The function receives the numbers by reference as a [cpp:vector]({cpp:vector}).',
            '##4## Slow and fast both begin at index 0, forming a tortoise and hare. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##5## The [cpp:vector]({cpp:vector}) acts as a linked list where each value is the next index.',
            '##6## Slow moves one step by looking up nums[slow]. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##7## Fast moves two steps by looking up nums[nums[fast]]. [Floyd\'s algorithm](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##8## The loop ends when both pointers collide inside the cycle. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##9## Reset slow to the head of the list to locate the cycle entrance. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##14## The duplicate number equals the cycle entry point found above. [ref](https://en.cppreference.com/w/cpp/container/vector)',
            '##16## [cpp:main]({cpp:main}) is the entry point of the program.',
            '##17## Build the test [cpp:vector]({cpp:vector}) with one duplicated value.',
            '##18## [cpp:cout]({cpp:cout}) prints the result.',
            '~~~',
            '',
            '~~~explain',
            'lang: java',
            'group: findduplicate',
            'import java.util.*;',
            'class Main {',
            '    public static int findDuplicate(int[] nums) {',
            '        int slow = nums[0], fast = nums[0];',
            '        do {',
            '            slow = nums[slow];',
            '            fast = nums[nums[fast]];',
            '        } while (slow != fast);',
            '        slow = nums[0];',
            '        while (slow != fast) {',
            '            slow = nums[slow];',
            '            fast = nums[fast];',
            '        }',
            '        return slow;',
            '    }',
            '    public static void main(String[] args) {',
            '        Scanner sc = new Scanner(System.in);',
            '        int[] nums = {1, 3, 4, 2, 2};',
            '        System.out.print(findDuplicate(nums));',
            '    }',
            '}',
            '---',
            '##2## [java:class]({java:class}) Main wraps the static methods used by the runner.',
            '##3## The method applies Floyd\'s cycle detection to the input array. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##4## Both pointers begin at index 0 before entering the loop. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##5## The do block guarantees at least one iteration before comparing pointers. [ref](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/while.html)',
            '##6## Slow advances one step using nums as a next-pointer table. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##7## Fast advances two steps, so the gap shrinks by one each iteration. [Floyd\'s cycle detection](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##9## Reset slow to the head while fast stays inside the cycle. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##10## This phase moves both pointers one step at a time until they meet. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##14## [java:return]({java:return}) hands the duplicate back to the caller.',
            '##16## [java:main]({java:main}) is the entry point executed by the JVM.',
            '##17## [java:scanner]({java:scanner}) is created to read from standard input.',
            '##19## [java:System]({java:System}).out.print writes the answer without a trailing newline.',
