            '##5## Slow moves by one index lookup in the [python:list]({python:list}).',
            '##6## Fast moves by two lookups, covering twice the distance per step. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##7## [python:if]({python:if}) the two pointers collide, the cycle has been detected.',
            '##9## Reset slow to the head to find the entrance of the cycle. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##10## This second loop advances both pointers one step at a time. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
            '##13## The entry point of the cycle is the duplicate value. [ref](https://en.wikipedia.org/wiki/Cycle_detection)',
