            '~~~problem',
            'title: "48. Rotate Image"',
            'difficulty: medium',
            'source: LeetCode 48 · Amazon, Microsoft, Google',
            'tags: array, matrix',
            'statement: Given an n x n matrix, rotate it 90 degrees clockwise in place and print the result.',
            'approach: First transpose the matrix so rows become columns, then reverse each row. The transpose and row reversal together produce the clockwise rotation in O(n^2) time and O(1) extra space.',
            'time: O(n^2)',
            'space: O(1)',
            'solution: rotateimage',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: rotateimage',
            '#include <stdio.h>',
            'int main() {',
            '    int a[3][3] = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};',
            '    int n = 3, i, j, t;',
            '    for (i = 0; i < n; i++)',
            '        for (j = i + 1; j < n; j++) {',
            '            t = a[i][j];',
            '            a[i][j] = a[j][i];',
            '            a[j][i] = t;',
            '        }',
            '    for (i = 0; i < n; i++)',
            '        for (j = 0; j < n / 2; j++) {',
            '            t = a[i][j];',
            '            a[i][j] = a[i][n - 1 - j];',
            '            a[i][n - 1 - j] = t;',
            '        }',
            '    for (i = 0; i < n; i++) {',
            '        for (j = 0; j < n; j++)',
            '            printf("%d ", a[i][j]);',
            '        printf("\\n");',
            '    }',
            '    return 0;',
            '}',
            '---',
            '##2## [c:main]({c:main}) is the program entry point.',
            '##3## A fixed-size 2D [c:array]({c:array}) stores the 3x3 sample matrix.',
            '##4## n holds the dimension; i, j, t are loop and swap temporaries. [ref](https://en.cppreference.com/w/c/language/for)',
            '##5## Outer [c:for]({c:for}) walks over every row.',
            '##6## Inner [c:for]({c:for}) only visits cells above the main diagonal.',
            '##7## t temporarily stores a[i][j] before the swap. [ref](https://en.wikipedia.org/wiki/Transpose)',
            '##8## Replace the upper-triangle cell with its mirrored value. [ref](https://en.wikipedia.org/wiki/Transpose)',
            '##9## Write the saved value into the lower triangle, completing the transpose. [ref](https://en.wikipedia.org/wiki/Transpose)',
            '##11## A second pass over rows prepares the reversal step. [ref](https://en.cppreference.com/w/c/language/for)',
            '##12## [c:for]({c:for}) covers the first half of each row for mirror swapping.',
            '##14## Mirror the element at column n-1-j within the [c:array]({c:array}).',
            '##19## [c:printf]({c:printf}) prints each rotated value.',
            '##20## [c:printf]({c:printf}) emits a newline after every row.',
            '##22## [c:return]({c:return}) 0 ends the program.',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: rotateimage',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int main() {',
            '    vector<vector<int>> a = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};',
            '    int n = a.size();',
            '    for (int i = 0; i < n; i++)',
            '        for (int j = i + 1; j < n; j++)',
            '            swap(a[i][j], a[j][i]);',
            '    for (int i = 0; i < n; i++)',
            '        reverse(a[i].begin(), a[i].end());',
            '    for (int i = 0; i < n; i++) {',
            '        for (int j = 0; j < n; j++)',
            '            cout << a[i][j] << " ";',
            '        cout << "\\n";',
            '    }',
            '    return 0;',
            '}',
            '---',
            '##3## [cpp:main]({cpp:main}) is the entry point of the program.',
            '##4## A [cpp:vector]({cpp:vector}) of vectors holds the square matrix.',
            '##5## n is derived from the outer [cpp:vector]({cpp:vector}) size.',
            '##6## The outer loop selects each row. [ref](https://en.cppreference.com/w/cpp/language/for)',
            '##7## The inner loop starts at i+1 to stay above the diagonal. [ref](https://en.wikipedia.org/wiki/Transpose)',
            '##8## swap mirrors the symmetric pair to perform the transpose. [ref](https://en.cppreference.com/w/cpp/algorithm/swap)',
            '##9## A second pass iterates over all rows. [ref](https://en.cppreference.com/w/cpp/language/for)',
            '##10## reverse flips each row, yielding the clockwise rotation. [ref](https://en.cppreference.com/w/cpp/algorithm/reverse)',
            '##13## [cpp:cout]({cpp:cout}) prints each value followed by a space.',
            '##14## [cpp:cout]({cpp:cout}) prints a newline after each row.',
            '##16## [cpp:main]({cpp:main}) returns 0 to indicate success.',
            '~~~',
            '',
            '~~~explain',
            'lang: java',
            'group: rotateimage',
            'import java.util.*;',
            'class Main {',
            '    public static void main(String[] args) {',
            '        Scanner sc = new Scanner(System.in);',
            '        int[][] a = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};',
            '        int n = a.length;',
            '        for (int i = 0; i < n; i++)',
            '            for (int j = i + 1; j < n; j++) {',
            '                int t = a[i][j];',
            '                a[i][j] = a[j][i];',
            '                a[j][i] = t;',
            '            }',
            '        for (int i = 0; i < n; i++)',
            '            for (int j = 0; j < n / 2; j++) {',
            '                int t = a[i][j];',
            '                a[i][j] = a[i][n - 1 - j];',
            '                a[i][n - 1 - j] = t;',
            '            }',
            '        for (int i = 0; i < n; i++) {',
            '            for (int j = 0; j < n; j++)',
            '                System.out.print(a[i][j] + " ");',
            '            System.out.println();',
            '        }',
            '    }',
            '}',
            '---',
            '##1## [java:import]({java:import}) brings in the java.util package.',
            '##2## [java:class]({java:class}) Main holds the entry method.',
            '##3## [java:main]({java:main}) is invoked by the JVM at startup.',
            '##4## [java:scanner]({java:scanner}) reads from standard input.',
            '##5## The 2D array literal defines the 3x3 sample matrix. [ref](https://docs.oracle.com/javase/8/docs/api/java/util/Arrays.html)',
            '##7## Outer [java:for]({java:for}) iterates over each row.',
            '##8## Inner [java:for]({java:for}) starts at i+1 so we only touch the upper triangle.',
            '##10## Assign the mirrored element to finish the transpose step. [ref](https://en.wikipedia.org/wiki/Transpose)',
            '##13## A second [java:for]({java:for}) pass processes every row.',
            '##14## [java:for]({java:for}) over the first half of each row mirrors the elements.',
            '##21## [java:System]({java:System}).out.print outputs each cell with a trailing space.',
            '##22## [java:System]({java:System}).out.println moves to the next line after each row.',
            '~~~',
            '',
            '~~~explain',
            'lang: python',
            'group: rotateimage',
            'def main():',
            '    a = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]',
            '    n = len(a)',
            '    for i in range(n):',
            '        for j in range(i + 1, n):',
            '            a[i][j], a[j][i] = a[j][i], a[i][j]',
            '    for i in range(n):',
            '        a[i].reverse()',
            '    for row in a:',
            '        print(" ".join(str(x) for x in row) + " ")',
            'main()',
            '---',
            '##1## [python:def]({python:def})ines main, the driver function.',
            '##2## The sample 3x3 matrix is stored as a [python:list]({python:list}) of lists.',
            '##3## n captures the number of rows of the [python:list]({python:list}).',
            '##4## Outer [python:for]({python:for}) iterates over the rows.',
            '##5## Inner [python:for]({python:for}) starts at i+1, covering the upper triangle.',
            '##6## Tuple swap mirrors the pair, performing the [python:list]({python:list}) transpose.',
            '##7## A second [python:for]({python:for}) pass processes each row.',
            '##8## reverse flips a row in place, completing the rotation. [Matrix transpose](https://en.wikipedia.org/wiki/Transpose)',
            '##9## [python:for]({python:for}) iterates over every row of the rotated matrix.',
            '##10## [python:print]({python:print}) joins the row values with spaces.',
            '##11## Calling [python:main]({python:main}) runs the program.',
            '~~~',
            '',
            '~~~explain',
            'lang: dart',
            'group: rotateimage',
            'void main() {',
            '  List<List<int>> a = [',
            '    [1, 2, 3],',
            '    [4, 5, 6],',
            '    [7, 8, 9]',
            '  ];',
            '  int n = a.length;',
            '  for (int i = 0; i < n; i++)',
            '    for (int j = i + 1; j < n; j++) {',
            '      int t = a[i][j];',
            '      a[i][j] = a[j][i];',
