            '  }',
            '}',
            '---',
            '##1## [dart:main]({dart:main}) is the Dart entry point.',
            '##2## The matrix is a [dart:List]({dart:List}) of [dart:List]({dart:List}) of ints.',
            '##7## n reads the [dart:length]({dart:length}) of the outer list.',
            '##8## Outer [dart:for]({dart:for}) selects each row.',
            '##9## Inner [dart:for]({dart:for}) starts at i+1 to stay above the diagonal.',
            '##10## t temporarily holds the value being swapped. [ref](https://dart.dev/language/variables)',
            '##11## Swap the upper-triangle element with its mirror below the diagonal. [ref](https://en.wikipedia.org/wiki/Transpose)',
            '##14## A second [dart:for]({dart:for}) pass visits each row.',
            '##15## reverse flips the row, yielding the 90-degree rotation. [Matrix transpose](https://en.wikipedia.org/wiki/Transpose)',
            '##16## Outer [dart:for]({dart:for}) loops over rows for output.',
            '##17## [dart:print]({dart:print}) joins the row values and prints them.',
