            '##7## m and n use the [dart:length]({dart:length}) of the matrix lists.',
            '##8## Four boundary variables delimit the current ring. [ref](https://en.wikipedia.org/wiki/Spiral)',
            '##9## res is an empty [dart:List]({dart:List}) that collects the spiral order.',
