            '~~~problem',
            'title: "73. Set Matrix Zeroes"',
            'difficulty: medium',
            'source: LeetCode 73 · Amazon, Meta, Oracle',
            'tags: array, matrix, hashing',
            'statement: Given an m x n matrix, set every cell in a row or column to 0 if that row or column contains at least one 0, doing it in place.',
            'approach: Use the first row and first column of the matrix as markers for zeroed rows and columns. Scan once to set markers plus flags for the first row and column, then zero interior cells, then fix the first row and column. This uses O(1) extra space.',
            'time: O(m*n)',
            'space: O(1)',
            'solution: setmatrixzero',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: setmatrixzero',
            '#include <stdio.h>',
            'int main() {',
            '    int a[3][3] = {{1, 1, 1}, {1, 0, 1}, {1, 1, 1}};',
            '    int m = 3, n = 3, i, j;',
            '    int row0 = 0, col0 = 0;',
            '    for (i = 0; i < m; i++)',
            '        for (j = 0; j < n; j++)',
            '            if (a[i][j] == 0) {',
            '                a[i][0] = 0;',
            '                a[0][j] = 0;',
            '                if (i == 0) row0 = 1;',
            '                if (j == 0) col0 = 1;',
            '            }',
            '    for (i = 1; i < m; i++)',
            '        for (j = 1; j < n; j++)',
            '            if (a[i][0] == 0 || a[0][j] == 0)',
            '                a[i][j] = 0;',
            '    if (row0)',
            '        for (j = 0; j < n; j++)',
            '            a[0][j] = 0;',
            '    if (col0)',
            '        for (i = 0; i < m; i++)',
            '            a[i][0] = 0;',
            '    for (i = 0; i < m; i++) {',
            '        for (j = 0; j < n; j++)',
            '            printf("%d ", a[i][j]);',
            '        printf("\\n");',
            '    }',
            '    return 0;',
            '}',
            '---',
            '##2## [c:main]({c:main}) is the program entry point.',
            '##3## The fixed-size [c:array]({c:array}) stores the 3x3 sample matrix with one zero.',
            '##6## [c:for]({c:for}) scans every row.',
            '##7## [c:for]({c:for}) scans every column.',
            '##8## [c:if]({c:if}) detects a zero cell.',
            '##11## [c:if]({c:if}) i is 0, remember to clear the first row later.',
            '##12## [c:if]({c:if}) j is 0, remember to clear the first column later.',
            '##14## Second pass [c:for]({c:for}) over the interior rows.',
            '##16## [c:if]({c:if}) the row or column marker is zero, the cell must be zeroed.',
            '##18## [c:if]({c:if}) the first row had a zero, clear all its cells.',
            '##21## [c:if]({c:if}) the first column had a zero, clear all its cells.',
            '##26## [c:printf]({c:printf}) prints each cell of the matrix.',
            '##27## [c:printf]({c:printf}) prints a newline after each row.',
            '##29## [c:return]({c:return}) 0 indicates success.',
            '~~~',
            '',
