            '##7## The outer loop scans each row. [ref](https://en.cppreference.com/w/cpp/language/for)',
            '##8## The inner loop scans each column. [ref](https://en.cppreference.com/w/cpp/language/for)',
            '##9## The condition detects a zero cell. [ref](https://en.cppreference.com/w/cpp/language/if)',
            '##11## Record the zeroed column in the first row of the [cpp:vector]({cpp:vector}).',
            '##12## When i is 0, set row0. [ref](https://en.cppreference.com/w/cpp/language/if)',
            '##13## When j is 0, set col0. [ref](https://en.cppreference.com/w/cpp/language/if)',
            '##15## The second pass covers interior rows. [ref](https://en.cppreference.com/w/cpp/language/for)',
            '##17## When a marker is zero, zero the interior cell. [ref](https://en.cppreference.com/w/cpp/language/if)',
            '##19## When row0 is set, clear the first row. [ref](https://en.cppreference.com/w/cpp/language/if)',
