            '##8## [java:for]({java:for}) scans each row.',
            '##9## [java:for]({java:for}) scans each column.',
            '##10## [java:if]({java:if}) detects a zero cell.',
            '##12## The zeroed column is recorded in the first row marker. [ref](https://en.wikipedia.org/wiki/In-place_algorithm)',
            '##13## [java:if]({java:if}) i is 0, set row0.',
            '##16## Second [java:for]({java:for}) pass over interior rows.',
            '##18## [java:if]({java:if}) a marker is zero, zero the interior cell.',
