            '~~~explain',
            'lang: python',
            'group: setmatrixzero',
            'def main():',
            '    a = [[1, 1, 1], [1, 0, 1], [1, 1, 1]]',
            '    m, n = len(a), len(a[0])',
            '    row0 = False',
            '    col0 = False',
            '    for i in range(m):',
            '        for j in range(n):',
            '            if a[i][j] == 0:',
            '                a[i][0] = 0',
            '                a[0][j] = 0',
            '                if i == 0:',
            '                    row0 = True',
            '                if j == 0:',
            '                    col0 = True',
