            '~~~problem',
            'title: "74. Search a 2D Matrix"',
            'difficulty: medium',
            'source: LeetCode 74 · Amazon, Microsoft, Bloomberg',
            'tags: array, binary search, matrix',
            'statement: Given a matrix where each row is sorted left to right and every row starts with a value greater than the previous row\'s last value, determine whether a target value exists in the matrix.',
            'approach: Flatten the m x n matrix into one virtual sorted array and run binary search on it. The midpoint index maps back to a cell using row = mid / cols and col = mid % cols, so the search takes only O(log(m*n)) comparisons with no extra space.',
            'time: O(log(m*n))',
            'space: O(1)',
            'solution: search2d',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: search2d',
            '#include <stdio.h>',
            'int main() {',
            '    int m = 3, cols = 4;',
            '    int a[3][4] = {{1, 3, 5, 7}, {10, 11, 16, 20}, {23, 30, 34, 60}};',
            '    int target = 3;',
            '    int lo = 0, hi = m * cols - 1, found = 0;',
            '    while (lo <= hi) {',
            '        int mid = lo + (hi - lo) / 2;',
            '        int row = mid / cols;',
            '        int col = mid % cols;',
            '        if (a[row][col] == target) {',
            '            found = 1;',
            '            break;',
            '        } else if (a[row][col] < target) {',
            '            lo = mid + 1;',
            '        } else {',
            '            hi = mid - 1;',
            '        }',
            '    }',
            '    printf("%s\\n", found ? "true" : "false");',
            '    return 0;',
            '}',
            '---',
