            'statement: Given a 2D grid of \'1\' (land) and \'0\' (water), count the number of islands, where an island is a group of adjacent \'1\' cells connected horizontally or vertically.',
            'approach: Scan every cell and whenever an unvisited \'1\' is found, increment the counter and flood fill that entire island by turning all reachable land cells into water with DFS or BFS. Each cell is visited at most once, giving O(m*n) time and O(m*n) worst-case recursion space.',
