            '# Hard Interview Questions',
            '',
            'The hardest tier tests optimization — binary search on answer, three-way partition, and multi-pointer sweeps. Expect to be asked for the complexity proof.',
            '',
            '~~~problem',
            'title: Split Array Largest Sum',
            'difficulty: hard',
            'source: LeetCode 410 · Google, Amazon',
            'tags: array, binary-search-answer, greedy',
            'statement: Split `nums` into `k` subarrays minimizing the largest subarray sum.',
            'approach: Binary search the answer between `max(nums)` and `sum(nums)`. Feasible(x) greedily packs elements so each part ≤ x; the predicate is monotone, so binary search the boundary.',
            'time: O(n log S), S = sum(nums)',
            'space: O(1)',
            'solution: splitarray',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: splitarray',
            '#include <stdio.h>',
            'int splitArray(int* nums, int n, int k) {',
            '    int lo = 0, hi = 0;',
            '    for (int i = 0; i < n; i++) {',
            '        if (nums[i] > lo) lo = nums[i];',
            '        hi += nums[i];',
            '    }',
            '    while (lo < hi) {',
            '        int mid = lo + (hi - lo) / 2;',
            '        int parts = 1, sum = 0;',
            '        for (int i = 0; i < n; i++) {',
            '            if (sum + nums[i] > mid) { parts++; sum = nums[i]; }',
            '            else sum += nums[i];',
            '        }',
            '        if (parts <= k) hi = mid;',
            '        else lo = mid + 1;',
            '    }',
            '    return lo;',
            '}',
            'int main() {',
            '    int nums[] = {7, 2, 5, 10, 8};',
            '    int n = 5, k = 2;',
            '    printf("%d\\n", splitArray(nums, n, k));',
            '    return 0;',
