            '~~~explain',
            'lang: cpp',
            'group: splitarray',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int splitArray(vector<int>& nums, int k) {',
            '    long lo = *max_element(nums.begin(), nums.end());',
            '    long hi = accumulate(nums.begin(), nums.end(), 0L);',
            '    while (lo < hi) {',
            '        long mid = lo + (hi - lo) / 2;',
            '        int parts = 1;',
            '        long sum = 0;',
            '        for (int x : nums) {',
            '            if (sum + x > mid) { parts++; sum = x; }',
            '            else sum += x;',
            '        }',
            '        if (parts <= k) hi = mid;',
            '        else lo = mid + 1;',
            '    }',
            '    return lo;',
            '}',
            'int main() {',
            '    vector<int> nums = {7, 2, 5, 10, 8};',
            '    cout << splitArray(nums, 2) << "\\n";',
            '    return 0;',
            '}',
