            'public class Main {',
            '    static int splitArray(int[] nums, int k) {',
            '        long lo = 0, hi = 0;',
            '        for (int x : nums) { lo = Math.max(lo, x); hi += x; }',
            '        while (lo < hi) {',
            '            long mid = lo + (hi - lo) / 2;',
            '            int parts = 1;',
            '            long sum = 0;',
            '            for (int x : nums) {',
            '                if (sum + x > mid) { parts++; sum = x; }',
            '                else sum += x;',
            '            }',
            '            if (parts <= k) hi = mid;',
            '            else lo = mid + 1;',
            '        }',
            '        return (int) lo;',
            '    }',
            '    public static void main(String[] args) {',
            '        int[] nums = {7, 2, 5, 10, 8};',
            '        System.out.println(splitArray(nums, 2));',
            '    }',
            '}',
