            '~~~problem',
            'title: First Missing Positive',
            'difficulty: hard',
            'source: LeetCode 41 · Amazon, Meta',
            'tags: array, index-sort, in-place',
            'statement: Smallest positive integer not in `nums`.',
            'approach: Treat the array as a hash table. In a first pass, swap each value in `[1, n]` to its index. Then scan for the first index whose value is wrong — that index + 1 is the answer.',
            'time: O(n)',
            'space: O(1)',
            'solution: firstmissing',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: firstmissing',
            '#include <stdio.h>',
            'void swap(int* a, int* b) { int t = *a; *a = *b; *b = t; }',
            'int firstMissingPositive(int* nums, int n) {',
            '    for (int i = 0; i < n; i++) {',
            '        while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {',
            '            swap(&nums[i], &nums[nums[i] - 1]);',
            '        }',
            '    }',
            '    for (int i = 0; i < n; i++) {',
            '        if (nums[i] != i + 1) return i + 1;',
            '    }',
            '    return n + 1;',
            '}',
            'int main() {',
            '    int nums[] = {3, 4, -1, 1};',
            '    int n = 4;',
            '    printf("%d\\n", firstMissingPositive(nums, n));',
            '    return 0;',
            '}',
            '---',
            '##1## Standard I/O header. [stdio]({c:stdio})',
            '##2## Swap helper function. [Functions](https://www.learn-c.org/en/Functions)',
            '##3## Function returns first missing positive. [Functions](https://www.learn-c.org/en/Functions)',
            '##4## Place each value at its correct index. [For loops]({c:for})',
            '##5## Valid range and not already placed. [While loops](https://www.learn-c.org/en/While_loops)',
            '##6## Swap to correct position. [Arrays]({c:array})',
            '##9## Find first misplaced value. [For loops]({c:for})',
            '##10## Index + 1 is the answer. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##12## All 1..n present. [return]({c:return})',
            '##13## Entry point. [main]({c:main})',
            '##15## Print result. [printf]({c:printf})',
            '##16## Exit successfully. [return]({c:return})',
            '~~~',
            '',
