            '~~~problem',
            'title: Trapping Rain Water',
            'difficulty: hard',
            'source: LeetCode 42 · Amazon, Google',
            'tags: array, two-pointers, prefix-max',
            'statement: Given elevation map heights, compute how much water can be trapped.',
            'approach: Water at `i` = `min(leftMax[i], rightMax[i]) - h[i]`. Compute prefix and suffix maxima, or do it with two pointers keeping running maxima from both ends in O(1) space.',
            'time: O(n)',
            'space: O(1) (two-pointer) / O(n) (prefix arrays)',
            'solution: trappingwater',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: trappingwater',
            '#include <stdio.h>',
            'int trap(int* h, int n) {',
            '    int l = 0, r = n - 1, lMax = 0, rMax = 0, water = 0;',
            '    while (l < r) {',
            '        if (h[l] < h[r]) {',
            '            if (h[l] >= lMax) lMax = h[l];',
            '            else water += lMax - h[l];',
            '            l++;',
            '        } else {',
            '            if (h[r] >= rMax) rMax = h[r];',
            '            else water += rMax - h[r];',
            '            r--;',
            '        }',
            '    }',
            '    return water;',
            '}',
            'int main() {',
            '    int h[] = {0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1};',
            '    int n = 12;',
            '    printf("%d\\n", trap(h, n));',
            '    return 0;',
            '}',
            '---',
            '##1## Standard I/O header. [stdio]({c:stdio})',
            '##2## Function returns trapped water. [Functions](https://www.learn-c.org/en/Functions)',
            '##3## Two pointers and running maxima. [Variables](https://www.learn-c.org/en/Variables)',
            '##4## Loop until pointers meet. [While loops](https://www.learn-c.org/en/While_loops)',
            '##5## Process shorter side. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##6## Update left maximum. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##7## Water trapped at this position. [Variables](https://www.learn-c.org/en/Variables)',
            '##8## Move left pointer. [Variables](https://www.learn-c.org/en/Variables)',
            '##10## Update right maximum. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##11## Water trapped at this position. [Variables](https://www.learn-c.org/en/Variables)',
            '##12## Move right pointer. [Variables](https://www.learn-c.org/en/Variables)',
            '##15## Return total water. [return]({c:return})',
            '##16## Entry point. [main]({c:main})',
            '##17## Height array. [Arrays]({c:array})',
            '##19## Print result. [printf]({c:printf})',
            '##20## Exit successfully. [return]({c:return})',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: trappingwater',
            '#include <bits/stdc++.h>',
