            '~~~problem',
            'title: Sliding Window Maximum',
            'difficulty: hard',
            'source: LeetCode 239 · Amazon, Facebook',
            'tags: array, deque, sliding-window',
            'statement: Maximum of every window of size `k`.',
            'approach: Monotonic deque holding candidate indices, decreasing by value. New element evicts smaller values from the back; expired indices pop from the front. The front is always the window max.',
            'time: O(n)',
            'space: O(k)',
            'solution: slidingwindowmax',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: slidingwindowmax',
            '#include <stdio.h>',
            'int* maxSlidingWindow(int* nums, int n, int k, int* returnSize) {',
            '    int* result = (int*)malloc((n - k + 1) * sizeof(int));',
            '    *returnSize = n - k + 1;',
            '    int deque[n], front = 0, back = 0;',
            '    for (int i = 0; i < n; i++) {',
            '        while (front < back && nums[deque[back - 1]] <= nums[i]) back--;',
            '        deque[back++] = i;',
            '        if (deque[front] <= i - k) front++;',
            '        if (i >= k - 1) result[i - k + 1] = nums[deque[front]];',
            '    }',
            '    return result;',
            '}',
            'int main() {',
            '    int nums[] = {1, 3, -1, -3, 5, 3, 6, 7};',
            '    int n = 8, k = 3, returnSize;',
            '    int* result = maxSlidingWindow(nums, n, k, &returnSize);',
            '    for (int i = 0; i < returnSize; i++) printf("%d ", result[i]);',
            '    printf("\\n");',
            '    free(result);',
            '    return 0;',
            '}',
            '---',
            '##1## Standard I/O header. [stdio]({c:stdio})',
            '##2## Function returns max of each window. [Functions](https://www.learn-c.org/en/Functions)',
            '##3## Allocate result array. [malloc]({c:malloc})',
            '##4## Result size = n - k + 1. [Variables](https://www.learn-c.org/en/Variables)',
            '##5## Monotonic deque (index array). [Arrays]({c:array})',
            '##6## Process each element. [For loops]({c:for})',
            '##7## Evict smaller values from back. [While loops](https://www.learn-c.org/en/While_loops)',
            '##8## Add current index to deque. [Arrays]({c:array})',
            '##9## Remove expired index from front. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##10## Record max once window is full. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##12## Return result. [return]({c:return})',
            '##13## Entry point. [main]({c:main})',
            '##15## Print result. [For loops]({c:for})',
            '##17## Free memory. [free]({c:free})',
            '##18## Exit successfully. [return]({c:return})',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: slidingwindowmax',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'vector<int> maxSlidingWindow(vector<int>& nums, int k) {',
            '    vector<int> result;',
            '    deque<int> dq;',
            '    for (int i = 0; i < nums.size(); i++) {',
            '        while (!dq.empty() && nums[dq.back()] <= nums[i]) dq.pop_back();',
            '        dq.push_back(i);',
            '        if (dq.front() <= i - k) dq.pop_front();',
            '        if (i >= k - 1) result.push_back(nums[dq.front()]);',
            '    }',
            '    return result;',
            '}',
            'int main() {',
            '    vector<int> nums = {1, 3, -1, -3, 5, 3, 6, 7};',
            '    for (int x : maxSlidingWindow(nums, 3)) cout << x << " ";',
            '    cout << "\\n";',
            '    return 0;',
            '}',
