DB["interview/theory"] = {  
        title: 'Theory Questions',
        crumbs: ['Home', 'Data Structures', 'Array', 'Interview Questions', 'Theory Questions'],
        tags: ['interview', 'theory', 'array', 'concepts'],
        content: [
            '# Theory Questions',
            '',
            'Conceptual questions interviewers ask about arrays. Answer with a definition, a complexity, and a concrete example.',
            '',
            '## Q1: Why is array access O(1)?',
            '',
            'Elements are stored contiguously. The address of `arr[i]` is computed arithmetically as `base + i * sizeof(type)`, so no traversal is needed — it is a single memory access.',
            '',
            '## Q2: Static vs dynamic arrays — differences?',
            '',
            'A **static** array has a fixed size decided at compile time; it cannot grow. A **dynamic** array (vector, ArrayList) grows by allocating a larger block and copying when full — amortized O(1) append. Static is faster and zero-extra-space; dynamic is flexible.',
            '',
            '## Q3: When would you choose an array over a linked list?',
            '',
            'For **indexed access** (O(1) vs O(n)), **cache locality** (contiguous memory), and **lower memory overhead** (no per-node pointers). Choose a linked list only for frequent insertion/deletion at a known position and when you never need random access.',
            '',
            '## Q4: Explain cache locality.',
            '',
            'The CPU moves memory to cache in fixed-size lines. Consecutive array elements share lines, so scanning an array misses the cache rarely. Linked-list nodes scattered in memory cause a cache miss per node.',
            '',
            '## Q5: What is the complexity of inserting into the middle of an array?',
            '',
            'O(n) — every element after the insertion point shifts right by one (or left for deletion). This is why insert-heavy structures like linked lists or balanced trees exist.',
            '',
            '## Q6: How would you reverse an array in O(1) space?',
            '',
            'Two pointers: swap `arr[l]` and `arr[r]`, advance `l++`/`r--` until they cross. O(n) time, O(1) extra space.',
            '',
            '## Q7: What is amortized analysis, in the context of dynamic arrays?',
            '',
            'Resizing copies `n` elements, but a resizing happens only every `n/2` appends on doubling. The expensive copies are "paid for" by the cheap appends, giving **O(1) amortized** per append and O(n) worst-case for a single one.',
            '',
            '## Q8: Difference between the difference array and prefix sum?',
            '',
            'Prefix sum answers **range-sum queries** in O(1) after O(n) build. Difference array applies **range updates** in O(1) each, materializing the final array in one O(n) pass. They are inverse operations.',
            '',
            '> [!success] Delivery tip',
            '> Answer in three beats: define → complexity → example. "Access is O(1) because addresses are arithmetic; for example `arr[999]` is one hop from `base`."'
        ].join('\n')
  };
